  settings_search_idx_fda: 'O macOS revogou o Acesso Total ao Disco do Xenon. Acontece a cada atualização, porque a permissão está ligada à assinatura da app. Enquanto faltar, o Xenon não indexa a tua pasta pessoal: caso contrário o macOS pediria permissão para Secretária, Documentos, Transferências, Fotografias e Música a cada varredura. Reativa em Definições do Sistema → Privacidade e Segurança → Acesso Total ao Disco: remove o Xenon da lista e adiciona-o de novo.',
