  'remote.intro_title': 'Controlo remoto seguro do PC',
  'remote.intro_p1': 'Permite aceder ao ambiente de trabalho do PC a partir de um smartphone ou tablet através da tua rede privada Tailscale (VPN ponto a ponto). A transmissão de vídeo é feita pelo Sunshine; o cliente gratuito Moonlight corre no teu telemóvel.',
  'remote.intro_p2': 'O Sunshine e o Tailscale são instalados via winget (o gestor de pacotes oficial da Microsoft) diretamente a partir dos seus repositórios oficiais.',
  'remote.intro_p3': 'O servidor do painel nunca fica exposto à internet. A ligação fica inteiramente dentro da tua rede Tailscale.',
