  ra_guide_s1: 'Liga o acesso a partir de outros dispositivos',
  ra_guide_s1_body: 'Está desligado até o ligares. Enquanto está desligado, o Xenon responde a este PC e a mais nada.',
  ra_guide_s2: 'Aponta o telemóvel ao código QR',
  ra_guide_s2_body: 'O código é um convite, não uma palavra-passe: dura três minutos e deixa de servir ao fim de algumas tentativas erradas. O painel abre no browser do telemóvel. Não há nada para instalar no telemóvel.',
  ra_guide_s2_wait: 'Disponível assim que o interruptor acima estiver ligado.',
  ra_guide_s3: 'Adiciona-o ao ecrã principal do telemóvel',
  ra_guide_s3_body: 'No iPhone carrega em Partilhar e depois Adicionar ao ecrã principal. No Android o Chrome oferece-se para instalar. A partir daí o Xenon abre com o ícone próprio, em ecrã inteiro, e é aí que o microfone e as notificações funcionam.',
  ra_guide_s4: 'Liga o endereço seguro',
  ra_guide_s4_body: 'Dá a este PC um nome só dele que funciona de qualquer lado, por uma ligação cifrada. Usa o Tailscale, que é grátis, e o Xenon instala-o e entra por ti. Não estás a criar conta nenhuma com o Xenon.',
  ra_guide_s5: 'Liga os certificados HTTPS na tua conta Tailscale',
  ra_guide_s5_body: 'É o único passo que o Xenon não pode fazer por ti. Abre a consola de administração do Tailscale, desce até HTTPS Certificates e carrega em Enable. É grátis em qualquer plano. Depois volta aqui: o Xenon continuou à espera.',
  ra_guide_s6: 'Instala o Tailscale no telemóvel, mesma conta',
  ra_guide_s6_body: 'Vai à App Store ou ao Google Play, entra com a mesma conta que acabaste de usar e liga o interruptor dele. É o passo que toda a gente esquece. Quando falta, o telemóvel diz que nem consegue abrir o endereço: não está nada avariado, aquele endereço só existe dentro da tua rede.',
  ra_guide_s7: 'Emparelha o telemóvel outra vez no novo endereço',
  ra_guide_s7_body: 'Carrega em Adicionar dispositivo no passo 2 e lê outra vez. O browser prende o emparelhamento ao endereço em que foi feito, por isso um telemóvel emparelhado no endereço de casa não está emparelhado no seguro. Daí em diante só precisas do novo, em casa e fora.',
  ra_guide_done_title: 'A configuração está feita',
  ra_guide_done_body: 'O telemóvel está emparelhado. Última coisa: o Xenon deve continuar a abrir também neste PC?',
  ra_guide_keep: 'Manter também aqui',
  ra_guide_hide: 'Esconder o Xenon neste PC',
  ra_guide_hide_note: 'Escondê-lo faz com que o Xenon deixe de abrir neste PC, também ao iniciar sessão. Continua a correr em segundo plano, por isso o telemóvel mantém-se a funcionar. Trazes a janela de volta pelo ícone do Xenon ao lado do relógio, ou em Definições e depois Ecrã.',
  ra_guide_hide_browser: 'Isto é o painel dentro de um browser, por isso não há janela para esconder. Na aplicação Xenon podes também escolher que deixe de abrir neste PC.',
